import { cn } from "@/lib/utils"

// Stand-in: relies on an animate-spotlight class the item does not define.
export const Spotlight = ({ className, fill }: { className?: string; fill?: string }) => {
  return (
    <svg className={cn("pointer-events-none absolute animate-spotlight opacity-0", className)} viewBox="0 0 100 100" fill="none">
      <ellipse cx="50" cy="50" rx="50" ry="10" fill={fill || "white"} fillOpacity="0.2" />
    </svg>
  )
}
